import {join} from 'node:path';
import {MediaTaskService} from '../../src/jobs/media-tasks.ts';
const [directory,url]=process.argv.slice(2),connection={id:'local-image',name:'Local fixture',protocol:'images',baseUrl:url+'/v1',auth:'none',credentialRef:'',enabled:true,revision:1,requestTimeoutMs:1000,concurrency:2},model={id:'image',connectionId:connection.id,model:'image-test',name:'Fixture',enabled:true,inputModalities:['text'],outputModalities:['image'],parameters:{}};
const service=new MediaTaskService(directory,{async resolve(){return {connection,model};},async credential(){return undefined;}},{async databasePath(){return join(directory,'.studio','state.sqlite');},async inspect(){return {revision:0,shotIds:[]};},async readImage(){throw new Error('not used');},async validateArtifact(){return {};},async applyResult(){throw new Error('not used');}},{pollIntervalMs:5});
process.send({ready:true});
process.once('message',async()=>{try{const task=await service.generate({clientRequestId:'cross-process-generation',projectId:'film',expectedRevision:0,operation:'text-to-image',prompt:'one shared supplier request'});for(let count=0;count<1000;count++){const current=await service.get(task.id);if(current.phase==='ready'){process.send({id:task.id,phase:current.phase});return;}await new Promise(resolve=>setTimeout(resolve,10));}throw new Error('shared task did not complete');}catch(error){process.send({error:error.stack??String(error)});}finally{await service.dispose();process.disconnect();}});
